extends Node

signal coin_changed(new_count: int)

var _count: int = 0
const SAVE_PATH = "user://save.json"

func _ready() -> void:
	load_data()

func _notification(what: int) -> void:
	if what == NOTIFICATION_WM_CLOSE_REQUEST:
		save()

func add_coin() -> void:
	_count += 1
	coin_changed.emit(_count)

func get_count() -> int:
	return _count

func save() -> void:
	var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file:
		file.store_string(JSON.stringify({"count": _count}))

func load_data() -> void:
	if FileAccess.file_exists(SAVE_PATH):
		var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
		if file:
			var json := JSON.parse_string(file.get_as_text())
			if json is Dictionary and json.has("count"):
				_count = int(json["count"])
	coin_changed.emit(_count)

extends CharacterBody2D

const SPEED = 300.0

func _physics_process(_delta: float) -> void:
	var direction_x := Input.get_axis("ui_left", "ui_right")
	var direction_y := Input.get_axis("ui_up", "ui_down")
	velocity.x = direction_x * SPEED
	velocity.y = direction_y * SPEED
	move_and_slide()

extends Area2D

signal collected

func _ready() -> void:
	body_entered.connect(_on_body_entered)

func _on_body_entered(body: Node2D) -> void:
	if body.name == "Player":
		collected.emit()
		Inventory.add_coin()
		queue_free()

extends CanvasLayer

@onready var label: Label = $Label

func _ready() -> void:
	Inventory.coin_changed.connect(_update_coins)
	_update_coins(Inventory.get_count())

func _update_coins(count: int) -> void:
	label.text = "Coins: " + str(count)

extends Node

signal coin_changed(new_count: int)

var _count: int = 0
const SAVE_PATH = "user://save.json"

func _ready() -> void:
	load_data()

func _notification(what: int) -> void:
	if what == NOTIFICATION_WM_CLOSE_REQUEST:
		save()

func add_coin() -> void:
	_count += 1
	coin_changed.emit(_count)

func get_count() -> int:
	return _count

func save() -> void:
	var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file:
		var json_string: String = JSON.stringify({"count": _count})
		file.store_string(json_string)

func load_data() -> void:
	if FileAccess.file_exists(SAVE_PATH):
		var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
		if file:
			var text: String = file.get_as_text()
			var json = JSON.parse_string(text)
			if json is Dictionary and json.has("count"):
				_count = int(json["count"])
	coin_changed.emit(_count)

